var FnDynamic={createTable:function(targetId,data){for(var $thead="<thead><tr>",$tbody="<tbody>",i=0;i<data.length;i++){var $obj=Object.keys(data[i]),$objLength=$obj.length;$tbody+="<tr>",$obj.map((function(key,index){0==i&&($thead+="<th>"+key+"</th>",index==$objLength-1&&($thead+="</tr></thead>")),$tbody+="<td>"+data[i][key]+"</td>",index==$objLength-1&&($tbody+="</tr>")}),0),i==data.length-1&&($tbody+="</tbody>",$("#"+targetId).html($thead+$tbody))}},setDdlValue:function(id,lDatas){for(var divCtrl=$("#"+id),i=0;i<lDatas.length;i++){var value=lDatas[i].value,text=lDatas[i].text,option=$("<option></option>");option.val(value).text(text),divCtrl.append(option)}}};